begin;
select set_config('cms_test.id',gen_random_uuid()::text,true);
select set_config('cms_test.category','cms-stat-'||gen_random_uuid()::text,true);
select set_config('cms_test.secret',repeat('v',43),true);
insert into cms_private.view_bridge(environment,secret_hash) values('preview',encode(sha256(convert_to(current_setting('cms_test.secret'),'UTF8')),'hex')) on conflict(environment) do update set secret_hash=excluded.secret_hash;
insert into public.categories(id,name,slug,sort_order) values(current_setting('cms_test.category'),current_setting('cms_test.category'),current_setting('cms_test.category'),99);
insert into public.posts(id,environment,title,slug,summary,content,category_id,status) values(current_setting('cms_test.id')::uuid,'preview','통계 테스트',current_setting('cms_test.category'),repeat('가',125),'[{"type":"text","text":"본문"}]',current_setting('cms_test.category'),'published');
select set_config('cms_test.version',(select version::text from public.posts where id=current_setting('cms_test.id')::uuid),true);
select set_config('cms_test.updated',(select updated_at::text from public.posts where id=current_setting('cms_test.id')::uuid),true);
set local role anon;
do $$ begin
 begin perform public.cms_record_post_view('preview',current_setting('cms_test.id')::uuid,repeat('a',64),current_setting('cms_test.secret'));raise exception 'Anonymous counter write accepted';exception when insufficient_privilege then null;end;
 begin perform public.cms_admin_statistics('preview');raise exception 'Anonymous statistics accepted';exception when insufficient_privilege then null;end;
 begin perform * from public.post_view_daily;raise exception 'Raw daily data leaked';exception when insufficient_privilege then null;end;
end $$;
reset role;
set local role service_role;
do $$ declare first jsonb; duplicate jsonb; other jsonb;begin
 begin perform public.cms_record_post_view('preview',current_setting('cms_test.id')::uuid,repeat('a',64),repeat('wrong',9));raise exception 'Invalid bridge credential accepted';exception when insufficient_privilege then null;end;
 first:=public.cms_record_post_view('preview',current_setting('cms_test.id')::uuid,repeat('a',64),current_setting('cms_test.secret'));
 duplicate:=public.cms_record_post_view('preview',current_setting('cms_test.id')::uuid,repeat('a',64),current_setting('cms_test.secret'));
 other:=public.cms_record_post_view('preview',current_setting('cms_test.id')::uuid,repeat('b',64),current_setting('cms_test.secret'));
 if first->>'counted'<>'true' or duplicate->>'counted'<>'false' or (other->>'viewCount')::integer<>2 then raise exception 'View deduplication/count failed';end if;
 if (select version::text from public.posts where id=current_setting('cms_test.id')::uuid)<>current_setting('cms_test.version') or (select updated_at::text from public.posts where id=current_setting('cms_test.id')::uuid)<>current_setting('cms_test.updated') then raise exception 'Views must not change post edit metadata';end if;
 update public.post_views set viewed_at=clock_timestamp()-interval '31 minutes' where post_id=current_setting('cms_test.id')::uuid and visitor_hash=repeat('a',64);
 first:=public.cms_record_post_view('preview',current_setting('cms_test.id')::uuid,repeat('a',64),current_setting('cms_test.secret'));
 if first->>'counted'<>'true' or (first->>'viewCount')::integer<>3 then raise exception 'Duplicate window failed to expire';end if;
end $$;
reset role;
insert into public.post_view_daily(post_id,environment,view_day,view_count) values(current_setting('cms_test.id')::uuid,'preview',(now() at time zone 'Asia/Seoul')::date-10,5),(current_setting('cms_test.id')::uuid,'preview',(now() at time zone 'Asia/Seoul')::date-40,100);
set local role anon;
do $$ declare weekly bigint;monthly bigint; listing jsonb;begin
 select period_views into weekly from cms_private.public_period_counts('preview',7) where post_id=current_setting('cms_test.id')::uuid;
 select period_views into monthly from cms_private.public_period_counts('preview',30) where post_id=current_setting('cms_test.id')::uuid;
 if weekly<>3 or monthly<>8 then raise exception 'Period boundaries failed';end if;
 listing:=public.cms_public_posts('preview',current_setting('cms_test.category'),'monthly',1);
 if (listing->'posts'->0->>'period_views')::integer<>8 then raise exception 'Period sorting failed';end if;
 if exists(select 1 from cms_private.public_period_counts('production',30) where post_id=current_setting('cms_test.id')::uuid) then raise exception 'Statistics environment mixed';end if;
end $$;
reset role;
update public.posts set status='private' where id=current_setting('cms_test.id')::uuid;
set local role service_role;
do $$begin if public.cms_record_post_view('preview',current_setting('cms_test.id')::uuid,repeat('c',64),current_setting('cms_test.secret'))->>'counted'<>'false' then raise exception 'Private post was counted';end if;end $$;
reset role;
set local role anon;
do $$begin if exists(select 1 from cms_private.public_period_counts('preview',30) where post_id=current_setting('cms_test.id')::uuid) then raise exception 'Private statistics leaked';end if;end $$;
reset role;
select set_config('cms_test.admin',gen_random_uuid()::text,true);
insert into auth.users(id,aud,role,email) values(current_setting('cms_test.admin')::uuid,'authenticated','authenticated','cms-stats-fixture@cms-test.invalid');
select set_config('request.jwt.claim.sub',current_setting('cms_test.admin'),true);
set local role authenticated;
do $$begin begin perform public.cms_admin_statistics('preview');raise exception 'Ordinary user statistics accepted';exception when insufficient_privilege then null;end;end $$;
reset role;
insert into public.admin_users(user_id,username) values(current_setting('cms_test.admin')::uuid,'cms_stats_fixture');
set local role authenticated;
do $$declare stats jsonb;begin stats:=public.cms_admin_statistics('preview');if jsonb_array_length(stats->'daily')<>30 or (stats->>'totalPosts')::integer<1 or (stats->>'totalViews')::integer<3 then raise exception 'Admin summary failed';end if;end $$;
reset role;
rollback;
